package com.meddibuddy.auth;
import com.meddibuddy.user.*;import com.meddibuddy.security.JwtService;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
@Service public class AuthService {public record Session(String token,String name,String email,String role){}private final AppUserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(AppUserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}public Session register(String name,String email,String password){if(users.existsByEmailIgnoreCase(email))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");return session(users.save(new AppUser(name,email,encoder.encode(password),Role.PATIENT)));}public Session login(String email,String password){var u=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect"));if(!encoder.matches(password,u.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect");return session(u);}private Session session(AppUser u){return new Session(jwt.issue(u.getEmail(),u.getRole().name()),u.getName(),u.getEmail(),u.getRole().name());}}
